// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.llm.localimport android.content.Contextimport android.os.Build/** * NOUS — Vulkan GPU Configuration. * * Determines whether GPU (Vulkan) acceleration should be used for llama.cpp. * Handles device-specific quirks (Adreno driver crashes, Mali context loss). * * @see <a href="docs/strategy/module-4-strategy-v2.1.md">§9 Vulkan Context Loss</a> */object VulkanConfig {    /**     * Whether GPU (Vulkan) should be used.     *     * Checks:     *   1. API level ≥ 29 (Vulkan 1.1 guaranteed)     *   2. Not in blacklist (known buggy GPU drivers)     *   3. Native library confirms GPU available     */    fun shouldUseGpu(gpuAvailable: Boolean): Boolean {        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.Q) return false        if (!gpuAvailable) return false        if (isBlacklistedGpu()) return false        return true    }    /**     * Check if this device's GPU is blacklisted (known crashes with llama.cpp Vulkan).     */    private fun isBlacklistedGpu(): Boolean {        val manufacturer = Build.MANUFACTURER?.lowercase() ?: ""        val model = Build.MODEL?.lowercase() ?: ""        val hardware = Build.HARDWARE?.lowercase() ?: ""        // Blacklisted: Adreno 6xx on Android 12 (driver crash with large context)        if (hardware.contains("qcom") && model.contains("sm8350")) {            return true        }        // Blacklisted: Mali-G76 on Android 11 (context loss)        if (hardware.contains("exynos") && model.contains("g76")) {            return true        }        return false    }    /**     * Get GPU info string for diagnostics.     */    fun getGpuInfo(): String {        return buildString {            append("Manufacturer: ${Build.MANUFACTURER}\n")            append("Model: ${Build.MODEL}\n")            append("Hardware: ${Build.HARDWARE}\n")            append("API: ${Build.VERSION.SDK_INT}\n")            append("Blacklisted: ${isBlacklistedGpu()}\n")        }    }}/** * NOUS — Lookahead Decoding Configuration. * * v2.1: Replaces Speculative Decoding (which needed 2 models). * Lookahead uses Jacobi iterations within a SINGLE model's forward pass. * Zero extra RAM. ~2x speedup. No draft model needed. * * @see <a href="docs/strategy/module-4-strategy-v2.1.md">§10 Lookahead Decoding</a> */data class LookaheadDecodingConfig(    /** Whether lookahead decoding is enabled. */    val enabled: Boolean = false,  // opt-in (enable when stable)    /** Number of tokens to predict per forward pass. */    val lookaheadTokens: Int = 4,    /** Jacobi iterations per step. */    val jacobiIterations: Int = 2,) {    init {        require(lookaheadTokens in 1..16) { "lookaheadTokens must be 1-16, got $lookaheadTokens" }        require(jacobiIterations in 1..8) { "jacobiIterations must be 1-8, got $jacobiIterations" }    }}/** * NOUS — Native Crash Watchdog. * * v2.1 Fix #2: Async-signal-safe crash handler. * * When llama.cpp C++ code crashes (SIGSEGV/SIGABRT), the signal handler * writes raw signal data to a pre-opened pipe (async-signal-safe `write()`). * A separate watchdog thread reads the pipe and handles recovery. * * Key: NEVER call JVM from signal handler (not async-signal-safe). * * @see <a href="docs/strategy/module-4-strategy-v2.1.md">§2 Native Crash Handler</a> */class CrashWatchdog(    /** Directory for crash log files. */    private val logDir: String,) {    @Volatile    private var monitoring: Boolean = false    @Volatile    private var pipeReadFd: Int = -1    /**     * Start monitoring for native crashes.     * Installs signal handler in native code (pipe + write, NOT JVM call).     */    fun start() {        if (monitoring) return        monitoring = true        // Install native crash handler        if (LlamaCppJni.ensureLoaded()) {            try {                LlamaCppJni.nativeInstallCrashHandler(logDir)            } catch (e: Throwable) {                // Native library not available — skip crash monitoring            }        }    }    /**     * Stop monitoring.     */    fun stop() {        monitoring = false    }    /**     * Whether crash monitoring is active.     */    val isMonitoring: Boolean get() = monitoring    companion object {        /** Signal names for logging. */        fun signalName(signal: Int): String = when (signal) {            11 -> "SIGSEGV"            6 -> "SIGABRT"            4 -> "SIGILL"            8 -> "SIGFPE"            7 -> "SIGBUS"            else -> "SIGNAL_$signal"        }    }}